/* DWARF original prototype: void SetWear(CHARACTER * this, BYTE bCell, LPITEM item) */

void __thiscall CHARACTER::SetWear(CHARACTER *this,BYTE bCell,LPITEM item)

{
  bool bVar1;
  
  if (bCell < 0x13) {
    SetItem(this,bCell + 'Z',item);
    if ((item == (LPITEM)0x0) && (bCell == '\x04')) {
      bVar1 = IsAffectFlag(this,0x14);
      if (bVar1) {
        RemoveAffect(this,0x3f);
      }
      bVar1 = IsAffectFlag(this,0x10);
      if (bVar1) {
        RemoveAffect(this,4);
        return;
      }
    }
  }
  else {
    _sys_err("SetWear",0x169,"CHARACTER::SetItem: invalid item cell %d",(uint)bCell);
  }
  return;
}
